(189,33,'rank_math_og_content_image','a:2:{s:5:\"check\";s:32:\"c6d9f3d21a06d2da68f9e54fec6b0636\";s:6:\"images\";a:1:{i:0;s:96:\"http://localhost:8000/wp-content/themes/coffee-cafe-corner/assets/images/about/why-were-here.jpg\";}}'),
